//  \u0427\u0435\u043C \u0431\u043E\u043B\u044C\u0448\u0435 \u0447\u0438\u0441\u043B\u043E, \u0442\u0435\u043C \u043C\u0430\u0448\u0438\u043D\u0430 \xAB\u043B\u0443\u0447\u0448\u0435\xBB. \u041B\u0443\u0447\u0448\u0430\u044F \u0441\u0442\u0430\u043D\u0435\u0442 \u0440\u043E\u0434\u0438\u0442\u0435\u043B\u0435\u043C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u043F\u043E\u043A\u043E\u043B\u0435\u043D\u0438\u044F.
//
//  car = {
//    progress     \u2014 \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u0438\u043A\u0441\u0435\u043B\u0435\u0439 \u043F\u0440\u043E\u0435\u0445\u0430\u043B\u0430 \u0432\u0434\u043E\u043B\u044C \u0442\u0440\u0430\u0441\u0441\u044B, \u0432\u0441\u0435 \u043A\u0440\u0443\u0433\u0438 \u0432\u043C\u0435\u0441\u0442\u0435 (\u043B\u0443\u0447\u0448\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442)
